      while((str = br.readLine()) != null){
        String[] input = str.split(" ");
        int sum = Integer.parseInt(input[0]) + Integer.parseInt(input[1]);
        sb.append(stringSize(sum)).append("\n");
      }
      System.out.print(sb);
    }catch(Exception e){
      System.out.println(e);
    }
  }
}

