public class Main {
    public static int divisors(int a, int b, int c) {
        int count = 0;
        if (b >= c && a <= c) count++;

        b = Math.min(b, c / 2);
        for (int i = a; i <= b; i++) {
            if (c % i == 0) count++;
        }
        return count;
    }

