                    new InputStreamReader(System.in));

            String sStr;
            while ((sStr = stdReader.readLine()) != null) {
                String[] inputs = sStr.split(" ");

                int a = Integer.valueOf(inputs[0]);
                int b = Integer.valueOf(inputs[1]);
                int c = Integer.valueOf(inputs[2]);

