class Main{
	public static void main(String args[]){
		Scanner sc = new Scanner(System.in);
	//宣言
		int
				sum;
		String
				input,
				output = "";

	//入力
		input = sc.next();
		//終了判定
		while(!(input.equals("0"))){
			sum = 0;
			for(int i = 0;i < input.length();i++){
