        Scanner sc = new Scanner(System.in);
        mainString = sc.nextLine();
        subString = sc.nextLine();

        for (int i = 0; i <= mainString.length() - subString.length(); i++) {
            loop(i);
        }

        System.out.println(subString.length() - maxLength);
    }

