        String ms = mainString.substring(start, start + subString.length());
        check(ms);
    }

    public static void check(String ms) {
        int count = 0;
        for (int i = 0; i < subString.length(); i++) {
            if (ms.charAt(i) == subString.charAt(i)) {
                count++;
            }
        }
        if (maxLength < count) {
            maxLength = count;
        }
    }
}

