    static class TaskB {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            //hgabca
            //aba
            String S = in.next();
            String T = in.next();
            int MIN = Integer.MAX_VALUE;
            for (int i = 0; i <= S.length() - T.length(); ++i) {
                int count = 0;
                for (int j = 0; j < T.length(); ++j) {
                    if (S.charAt(i + j) != T.charAt(j)) {
