class MultipleOfNine {

    public String check(String number) {
        String[] nums = number.split("");
        long total = 0;
        for (String num : nums) {
            int parsed = Integer.parseInt(num);
            total += parsed;
        }

        if (total % 9 == 0) {
            return "Yes";
        }
        return "No";
    }

