				continue;
			}
			if (tmp < tmpborder) {
				bordersum = bordersum.add(BigInteger.valueOf(tmpborder).subtract(BigInteger.valueOf(tmp)));
			} else {
				tmpborder = tmp;
			}
		}
		System.out.println(bordersum);
	}
}

