        InputStream inputstream = System.in;
        OutputStream outputstream = System.out;
        InputReader in = new InputReader(inputstream);
        PrintWriter out = new PrintWriter(outputstream);
        Task solver = new Task();
        solver.solve(in, out);
        out.flush();
    }

    static class Task {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = in.nextInt();
            int b[] = a.clone(); 
            for (int i = 0; i < n - 1; i++) {
                if (a[i] - a[i + 1] > 0)
                    a[i + 1] = a[i];
            }
            long stools=0;
            for(int i=0;i<n;i++){
                stools+=a[i]-b[i];
            }
            out.println(stools);
        }
    }
}

