		boolean ans = knapsack(weight, value, wt - 1, sum - weight[n - 1], n) || knapsack(weight, value, wt - 1, sum - weight[n - 1], n - 1) || knapsack(weight, value, wt, sum, n - 1);
		return ans;

	}
}





