        PrintWriter out = new PrintWriter(outputStream);
        BCraneAndTurtle solver = new BCraneAndTurtle();
        solver.solve(1, in, out);
        out.close();
    }

    static class BCraneAndTurtle {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.readInt();
            int legs = in.readInt();

            for (int i = 0; i <= n; i++) { // crane
                for (int j = 0; j <= n; j++) { // turtle
                    if ((i * 2 + j * 4) == legs && i + j == n) {
                        System.out.println("Yes");
//                    System.out.println("cranes =" + i + " turtles =" + j);
                        return;
                    }
                }
            }

            System.out.println("No");
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new RuntimeException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

