public class Main {
    public static void main(final String[] args) {
        final FastScanner scanner = new FastScanner(System.in);
        final int n = scanner.nextInt() % 10;

        switch (n) {
            case 3: {
                System.out.println("bon");
                return;
            }

            case 0:
            case 1:
            case 6:
            case 8: {
                System.out.println("pon");
                return;
            }

            default: {
                System.out.println("hon");
            }
        }
