public class Main{
	static FastScanner sc = new FastScanner();
	static PrintWriter out = new PrintWriter(System.out);
	static String S;
	//static int h;
	//static int w;
	static int n;
	static int m;
	//static char field [][];
	//final static int dx []= {0, 1};
	//final static int dy []= {1, 0};
	//static boolean seen[][];
	//static int ans [][];
