    static class Workout {
        public void solve(int testNumber, InputReader sc, PrintWriter w) {
              int n = sc.nextInt();
      		  int m = sc.nextInt();
      	      int ans = (n * (n - 1))/2+ (m * (m - 1))/ 2;
              w.println(ans);
        }

