	public static int combination(int num){
	   int comb = 0;
      int temp = 1;
      for(int i = num; i > num - 2; i--){
         temp *= i;
      }
      temp /= 2;
      if(temp != 0){
         comb = temp;
     	}
     	return comb;
	}
}

