		System.out.println(ans);
	}
	public static boolean isPal(String s) {
		int l = 0;
		int r = s.length() - 1;
		while(l <= r) {
			if(s.charAt(l) != s.charAt(r)) return false;
			l += 1;
			r -= 1;
		}
		return true;
	}
}

