            return;
        }

        l = ((n + 3)/2) - 1;
        r = n - 1;
        if(!isPalindrome(s , l , r)){
            System.out.println("No");
            return;
        }
        System.out.println("Yes");
        input.close();
    }

    public static boolean isPalindrome(String s , int l , int r ){
        while(l < r){
            if(s.charAt(l++) != s.charAt(r--)){
                return false;
            }
        }
        return true;
    }
}

