    int right2 = ((s.length() - 1 ) / 2) - 1;
    while(left1 <= right1){
      if(s.charAt(left1) != s.charAt(right1)){
        return false;
      }
      left1++;
      right1--;
    }
    while(left2 <= right1){
      if(s.charAt(left2) != s.charAt(right2)){
        return false;
      }
      left2++;
      right2--;
    }
    return true;
  }
