        boolean isKai = true;

        int len = s.length();

        int half = len / 2;

        char[] c = s.toCharArray();

        for (int i = 0; i < half; i++) {
            if (c[i] != c[len - 1 - i]) {
                isKai = false;
                break;
            }
        }

        return isKai;
    }
}

