	public static boolean is_Palindrome(String s, int n){
		boolean flag = true;
		if(n % 2 != 0){
			int n3 = (n - 1)/ 2;
			int i = 0;
			while(i < n3){
				if(s.charAt(i) != s.charAt(n - i - 1)){
					flag = false;
					break;
				}
				i++;
			}
		}
		else{
			int n3 = (n - 1)/ 2 + 1;
			int i = 0;
			while(i < n3){
				if(s.charAt(i) != s.charAt(n - i - 1)){
					flag = false;
					break;
				}
				i++;
			}
		}
		return flag;
	}

	}

