		System.out.println(count == 3 ? "Yes" : "No");
	}

	static boolean isPalindrome(String s){
		boolean flg = true;
		for(int i=0; i<s.length() / 2; i++){
			if(s.charAt(i) != s.charAt(s.length()-i-1)){
				flg = false;
				break;
			}
		}
		return flg;
	}
}

