    static class CTaxIncrease {
        public void solve(int testNumber, Scanner in, PrintWriter out) {

            int a = in.nextInt();
            int b = in.nextInt();
            int i = 1;
            while (i < 10000) {
                int e = (int) ((double) i * 0.08);
                int t = (int) ((double) i * 0.1);
                if (e == a && t == b) break;
                i++;
            }

            out.println(i == 10000 ? -1 : i);

        }

    }
}

