		PrintWriter pw = new PrintWriter(System.out);
		int a = sc.nextInt(), b = sc.nextInt(), c = sc.nextInt();

		if(((a == b)&&(a != c))||((a == c)&&(b != c))||((c == b)&&(a != c))){
			pw.print("Yes");
