    private static void solve(FastScanner in, PrintWriter out){
        int N = in.nextInt();
        String s = in.next();
        int n = s.length();
        int a[] = new int[n];
        for(int i=0;i<n;i++){
            a[i] = ((s.charAt(i)-'A')+N)%26;
        }
        for(int i=0;i<n;i++){
            out.write((char)('A'+a[i])+"");
        }
        out.write("\n");
    }
