    static class BROTN {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int shift = in.nextInt();
            String s = in.next();
            StringBuilder res = new StringBuilder();
            for (int i = 0; i < s.length(); i++) {
                int tmp = ((s.charAt(i) - 'A') + shift) % 26;
                char newC = (char) ('A' + tmp);
                res.append(newC);
            }
            out.println(res);
        }

    }
}

