		//開始０ポイントで、正解した人は１ポイントとし、
		//終了までにQ-Kポイント獲得すると突破に読み換える。
		for(int i=0;i<Q;i++) {
			points[A[i]-1]++;
		}

		for (int point :points ) {
			if(point>Q-K) {
				System.out.println("Yes");
