        sc.close();
    }

    private static int sln(int[] A, int[] B, int[] C, int n) {
        int res = 0;
        for (int i = 0; i < n; i++) {
            res += B[i];
            if (i > 0 && A[i] - A[i - 1] == 1) res += C[A[i] - 1];
        }
        return res;
    }
