        }
        sc.close();


        System.out.println(Buffet(N, 0, A, B, C));
    }
    public static int Buffet(int N, int index, int[] A, int[] B, int[] C) {
        if (index == N) {
            return 0;
        }
        int score = B[A[index]-1];
        if (index != 0 && A[index-1] + 1 == A[index]) {
            score += C[A[index-1]-1];
        }
        return score + Buffet(N, index + 1, A, B, C);
    }
}

