	private static int solve(int n, int[] b) {
		int r = b[0];
		for (int i = 0; i < n - 2; i++)
			if (b[i] <= b[i + 1])
				r += b[i];
			else
				r += b[i + 1];
		r += b[n - 2];
		return r;
	}
}

