    static class TaskA {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            String S = in.readString();
            String T = in.readString();
            int ans = 0;
            for (int i = 0; i < 3; i++) {
                if (S.charAt(i) == T.charAt(i)) {
