public class Main {

	public static long calc(long cnt) {
		if (cnt <= 1)
			return 0;
		long ans = 0;
		if (cnt % 2 == 0) {
			ans = cnt / 2;
			ans *= (cnt - 1);
		} else {
			ans = (cnt - 1) / 2;
			ans *= cnt;
		}
		return ans;
	}

	public static String mysort(String s) {
		char c[] = s.toCharArray();
