class AtCoder {

    final int N;
    Map<String, Integer> map;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        map = new HashMap<>();
        for (int i = 0; i < N; i++) {
            char[] ch = sc.next().toCharArray();
            Arrays.sort(ch);
            String s = String.valueOf(ch);
            int v = map.getOrDefault(s, 0);
            map.put(s, ++v);
        }
    }

    void solve(PrintWriter out) {
        long ans = 0;
        for (Map.Entry<String, Integer> e : map.entrySet()) {
            int v = e.getValue();
            ans += nCk(v, 2);
        }
        out.println(ans);
    }

    long nCk(long n, long k) {
        if (n < k) return 0;
        if (n == k) return 1;
        long x = 1;
        for (long i = 0; i < k; i++) {
            x = x * (n - i) / (i + 1);
        }
        return x;
    }
}

