        Map<String, Integer> map = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String str = sc.nextLine();
            List<String> list = new ArrayList<>();
            for (Character c : str.toCharArray()) {
                list.add(c.toString());
            }
            Collections.sort(list);
            StringJoiner sj = new StringJoiner("");
            for (String s : list) {
                sj.add(s);
            }
