                map.put(key, 1);
            }

        }
        sc.close();

        long count = 0;
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            int value = entry.getValue();
            if (value >= 2) {
                count += combi(value);
            }
        }
        System.out.print(count);
