    static class CGreenBin {
        public void solve(int testNumber, FastReader s, PrintWriter out) {
            int n = s.nextInt();
            String[] arr = new String[n];
            for (int i = 0; i < n; i++) {
                arr[i] = s.nextString();
            }

            HashMap<String, Integer> map = new HashMap<>();
            for (int i = 0; i < n; i++) {
                char[] charArr = arr[i].toCharArray();
