        }
        long answer = front(N, a_o, a_f, b_f);
        answer = Math.max(answer,back(N, a_o, a_f, b_f));
        System.out.println(answer);
    }
    private long front(int N, long[] o, long[] a, long[] b) {
        for (int i = 0; i < N; i++) {
            if (0 < b[i]) {
                if (b[i] < a[i]) {
                    a[i] -= b[i];
                    b[i] = 0;
                    continue;
                } else {
                    b[i] -= a[i];
                    a[i] = 0;
                }
            }
            if (b[i] < a[i+1]) {
                a[i+1] -= b[i];
                b[i] = 0;
            } else {
                b[i] -= a[i+1];
                a[i+1] = 0;
            }
        }
        long answer = 0;
        for (int i = 0; i < N + 1; i++) {
            answer += o[i] - a[i];
        }
        return answer;
    }
    private long back(int N, long[] o, long[] a, long[] b) {
        for (int i = N-1; 0 <= i; i--) {
            if (0 < b[i+1]) {
                if (b[i] < a[i+1]) {
                    a[i+1] -= b[i];
                    b[i] = 0;
                    continue;
                } else {
                    b[i] -= a[i+1];
                    a[i+1] = 0;
                }
            }
            if (b[i] < a[i]) {
                a[i] -= b[i];
                b[i] = 0;
            } else {
                b[i] -= a[i];
                a[i] = 0;
            }
        }
        long answer = 0;
        for (int i = 0; i < N + 1; i++) {
            answer += o[i] - a[i];
        }
        return answer;
    }
}

