        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
            int n = in.nextInt();
            long[] towns = new long[n+1];
            long[] heroes = new long[n];
            for (int i = 0; i < n+1; i++) {
                towns[i] = in.nextLong();
