        A[N-1] -= delL;
        ans += (delL + delR);
      } else {
        int delL = Math.min(A[i], b);
        A[i] -= delL;
        int delR = Math.min(A[i+1], b-delL);
        A[i+1] -= delR;
        ans += (delL + delR);
      }
    }
    System.out.println(ans);
  }
