		long r = 0;
		for (int i = 0; i < b.length; i++)
			for (int j = i; j <= i + 1; j++)
				if (a[j] > b[i]) {
					r += b[i];
					a[j] -= b[i];
					b[i] = 0;
				} else {
					r += a[j];
					b[i] -= a[j];
					a[j] = 0;
				}
		return r;
	}
}

