public class Main {

	public static void main(String[] args) {
		FastReader sc = new FastReader();
		int n = sc.nextInt();
		long res = 0;
		long[] streets = new long[n+1];
		long[] heroes = new long[n];

		for (int i = 0; i < (n + 1); i++) {
			long monster = sc.nextInt();
			streets[i] = monster;
		}

		for (int i = 0; i < n; i++) {
			long damage = sc.nextInt();
			heroes[i] = damage;
		}

		long left = 0;

		for (int i = 0; i < n; i++) {
			long damage = heroes[i];
			long monster = streets[i];
			if (monster > 0) {
				res += left;
				monster -= left;
			}

			if (damage >= monster) {
				res += monster;
				left = Math.min(damage-monster, streets[i+1]);
			} else {
				res += Math.min(damage, monster);;
				left = 0;
			}
		}

		if (left > 0 && streets[streets.length - 1] > 0) {
			res += left;
		}

		System.out.println(res);
	}

	static class FastReader { 
        BufferedReader br; 
        StringTokenizer st; 

        public FastReader() { 
            br = new BufferedReader(new InputStreamReader(System.in)); 
        } 

        String next() { 
            while (st == null || !st.hasMoreElements()) { 
                try { 
                    st = new StringTokenizer(br.readLine()); 
                } catch (IOException  e) { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        } 

        int nextInt() { 
            return Integer.parseInt(next()); 
        } 

        long nextLong() { 
            return Long.parseLong(next()); 
        } 

        double nextDouble() { 
            return Double.parseDouble(next()); 
        } 

        String nextLine() { 
            String str = ""; 
            try{ 
                str = br.readLine(); 
            } catch (IOException e) { 
                e.printStackTrace(); 
            } 
            return str; 
        } 
    } 
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        Integer towns = Integer.parseInt(sc.nextLine());
        String[] Monsters = sc.nextLine().split(" ");
        String[] Braves = sc.nextLine().split(" ");

        long huntCount = 0;
        for (int i = 0; i < towns; i++) {
            int firstMonsters = Integer.parseInt(Monsters[i]);
            int bravePower = Integer.parseInt(Braves[i]);

            if (firstMonsters <= bravePower) {
                // 1つ目の町は全滅できる
                huntCount += firstMonsters;

                int secondMonsters = Integer.parseInt(Monsters[i + 1]);
                int remainBravePower = bravePower - firstMonsters;
                if (remainBravePower >= secondMonsters) {
                    // 2個目の町も全滅できる
                    huntCount += secondMonsters;
                    Monsters[i + 1] = String.valueOf(0);
                } else {

                    // ちょっと残る
                    huntCount += remainBravePower;
                    Monsters[i + 1] = String.valueOf(secondMonsters - remainBravePower);
                }
            } else {

                // 1個目の町も全滅できないが何匹かは倒せる
                huntCount += bravePower;
            }
            System.err.println(huntCount);
        }

        System.err.println();
        System.out.println(huntCount);
    }
}

