		boolean chk = true;

		for (int i = 0; i < 4; i++) {
			if (x[i] != 1) {
				chk = false;
			}
		}

		// 結果出力
		if (chk) {
			System.out.println("Yes");
		} else {
			System.out.println("No");
		}

	}

}

