    static int sln(int[] A) {
        int n = A.length, res = 0;
        for (int i = 1; i < n - 1; i++) {
            if ((A[i] <= A[i - 1] && A[i] <= A[i + 1]) || (A[i] >= A[i - 1] && A[i] >= A[i + 1])) continue;
            res++;
        }
        return res;
