        for (int j = 0; j < n; j++) {
          if(j != i) {
            t += l + j;
          }
        }
        if(abs(total - res) > abs(total - t)) res = t;
      }

      final int ans = res;
      out.println(ans);
    }
    catch(IOException e) {
      System.err.println(e);
    }
  }

  int atoi(String s) { return Integer.parseInt(s); }
  long atol(String s) { return Long.parseLong(s); }

