    static class BBiteEating {
        public void solve(int testNumber, inputClass sc, PrintWriter out) {
            int n = sc.nextInt();
            int l = sc.nextInt();
            int sum = 0;
            for (int i = 0; i < n; i++) {
                sum += (l + i);
            }
            int diff = Math.abs(sum - (sum - l));
            int ans = sum - l;
            for (int i = 1; i < n; i++) {
                if (diff > Math.abs(sum - (sum - l - i))) {
                    ans = sum - l - i;
                    diff = Math.abs(sum - (sum - l - i));
                }
            }
            out.println(ans);
        }

