				s = b / c - a / c + 1;
			} else {
				s = b / c - a / c;
			}

			if (a % d == 0) {
				t = b / d - a / d + 1;
			} else {
				t = b / d - a / d;
			}

			if (a % cd == 0) {
				u = b / cd - a / cd + 1;
			} else {
				u = b / cd - a / cd;
			}

			long result = (b - a + 1) - (s + t - u);

			System.out.println(result);
		}

	}

