            bdac = B/D - A/D + 1;
        }else {
            bdac = B/D - A/D;
        }
        if(A % (C*D/saiyaku(C,D)) == 0) {
            bacd = B/(C*D/saiyaku(C,D)) - A/(C*D/saiyaku(C,D)) + 1;
        }else {
            bacd = B/(C*D/saiyaku(C,D)) - A/(C*D/saiyaku(C,D));
        }
        long count = bcac + bdac - bacd;
        System.out.println(B-A-count+1);

    }

