        if(x <= y) {
            return y;
        }else {
            return x;
        }
    }

    public static long saiyaku(long x, long y) {
        long w = 0;
        if(x < y) {
            w = x;
            x = y;
            y = w;
            return saiyaku(x, y);
        }
        w = y;
        y = x % y;
        x = w;
        if(y == 0) {
            return x;
        }else {

            return saiyaku(x, y);
        }
    }


