    private static long cnt(long a, long b, long c) {
        long consumed = (a - 1) % c;
        long rest = c - 1 - consumed;
        a += rest;
        return (b - a + 1 + c - 1) / c;
    }

    private static long lcm(long a, long b) {
        return a * b / gcd(a, b);
    }

    private static long gcd(long a, long b) {
        while (b > 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

