        long e = B / lcm - (A - 1) / lcm;
        long ans = B - A + 1 - c - d + e; 
        System.out.println(ans);
    }
    public static long gcd(long max, long min){
        if(max%min==0){
            return min;
        }
        min = gcd(min, max % min);
        return min;
    }
}

