class Gcd{

    public static long gcd(long m, long n){
        if(n==0) {return m;}
        if(m >= n) {return gcd(n, m % n);}

        if(m==0) {return n;}
        if(m < n) {return gcd(m, n % m);}

        return 0;
    }

}

