    }

    static long f(long W, long C, long D) {
        long quanty = W;
        quanty -= W / C;
        quanty -= W / D;
        quanty += W / lcm(C, D);
        return quanty;
    }

    static long lcm(long C, long D) {
        return C * D / gcd(C, D);
    }

    static long gcd(long C, long D) {
        return D > 0 ? gcd(D, C % D) : C;
    }

}

