	}

	static long num(long n, long c, long d) {
		long G = gcd(c, d);
		long L = c / G * d;
		return n - n / c - n / d + n / L;
	}

	static long gcd(long a, long b) {
		return b > 0 ? gcd(b, a % b) : a;
	}

	static long lcm(long a, long b) {
		return a * b / gcd(a, b);
	}
}

