        String[] s = stdR.readLine().split(" ");
        long A = Long.parseLong(s[0]);
        long B = Long.parseLong(s[1]);
        long C = Long.parseLong(s[2]);
        long D = Long.parseLong(s[3]);
        System.out.println((B - A + 1) - divider(A, B, C) - divider(A, B, D) + divider(A, B, lcm(C,D)));
    }

    public static long divider(long A, long B,long div) {
        long start = 0;
        long end = 0;
        if(A <= div) {
            start = div;
        }else {
            if(A % div == 0) {
                start = A;
            }else {
                start = A + div - A % div;
            }
        }

        if(B < div) {
          return 0;
        }else {
            end = B - B % div;
        }
        if(start > end)return 0;
        return (end - start) / div + 1;
    }

    private static long lcm(long m, long n) {
        return m * n / gcd(m, n);
    }

    private static long gcd(long m, long n) {
        if(m < n) return gcd(n, m);
        if(n == 0) return m;
        return gcd(n, m % n);
    }
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    long A = scan.nextLong();
    long B = scan.nextLong();
    long C = scan.nextLong();
    long D = scan.nextLong();
    long CD = leastCommonMultiple(C, D);

    long cStart;
    long dStart;
    long cdStart;
    if (A % C == 0) {
      cStart = A / C;
    } else {
      cStart = A / C + 1;
    }
    if (A % D == 0) {
      dStart = A / D;
    } else {
      dStart = A / D + 1;
    }
    if (A % CD == 0) {
      cdStart = A / CD;
    } else {
      cdStart = A / CD + 1;
    }

    long cEnd = B / C;
    long dEnd = B / D;
    long cdEnd = B / CD;

    long cn = cEnd - cStart + 1;
    long dn = dEnd - dStart + 1;
    long cdn = cdEnd - cdStart + 1;

    long result = B - A + 1 - cn - dn + cdn;

    System.out.println(result);

  }

  private static long leastCommonMultiple(long a, long b) {
    long temp;
    long c = a;
    c *= b;
    while ((temp = a % b) != 0) {
      a = b;
      b = temp;
    }
    return c / b;
  }
}

