        long tmp;
        long x = 0;
        long y = 0;
        if (x >= y) {
            x = a;
            y = b;
        } else {
            x = b;
            y = a;
        }
        while ((tmp = x % y) != 0) {
            x = y;
            y = tmp;
        }
        return y;
    }
