	private static long solve(long a, long b, long c, long d) {
		long r = 0;
		r += (b / c);
		r -= ((a - 1) / c);
		r += (b / d);
		r -= ((a - 1) / d);
		long x = gcm(c, d);
		x = c * d / x;
		r -= (b / x);
		r += ((a - 1) / x);
		return b - a + 1 - r;
	}

	private static long gcm(long c, long d) {
		if (c < d) {
			long x = c;
			c = d;
			d = x;
		}
		if (c % d == 0)
			return d;
		return gcm(d, c % d);
	}
}

