		long Q = B / D - (A - 1) / D;
		long R = B / lcm(C, D) - (A - 1) / lcm(C, D);

		long ans = (B - A + 1) - P - Q + R;

		System.out.println(ans);

	}

	public static long lcm(long a, long b) {
		return a * b / gcd(a, b);
	}

