		double ans = 0;
		for (int i = 1; i <= n; i++) {
			double tmp = 1;
			for (int j = 0; true; j++) {
				if ((0x1 << j) * i >= k) {
					break;
				}
				tmp /= 2;
			}

			ans += tmp;
//			pr.println(ans);
		}

