        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final int k = scanner.nextInt();

        double result = 0;

        for (int i = 1; i <= n; i++) {
            final double a = Math.log(k) / Math.log(2);
            final double b = Math.log(i) / Math.log(2);
            double ceil = Math.ceil(a - b);
            if(ceil < 0){
