class Solver {
	int[] b;
	int c;
	public Solver(int[] b, int c) {
		this.b = b;
		this.c = c;
	}
	boolean canSolve(int... a) {
		int value = c;
		for (int i = 0; i < b.length; i++) {
			value += a[i] * b[i];
		}
		return value > 0;
	}
}

