        }

        for(int i = 0;i < N;i++) {
            for(int j = 0;j < M;j++) {
                A[i][j] = nextInt();
            }
        }

        int ans = 0;
        for(int i = 0;i < N;i++) {
            int sum = C;
            for(int j = 0;j < M;j++) {
                sum += A[i][j] * B[j];
            }
            if (sum > 0) {
                ans++;
            }
        }

        out.println(ans);
    }

    public static void main(String[] args) {
