    public static int minCost(int[] h, int N) {
        int st1 = 0;
        int st2 = Math.abs(h[1] - h[0]);
        for (int i = 2; i < N; i++) {
            int next = Math.min(st2 + Math.abs(h[i] - h[i-1]), st1 + Math.abs(h[i] - h[i-2]));
