        for (int i = N-3; i >= 0; i--) {
            int hop1 = dp[i+1] + getDist(i,i+1);
            int hop2 = dp[i+2] + getDist(i,i+2);
            dp[i] = Math.min(hop1, hop2);
        }

        System.out.println(dp[0]);
    }
