    static int solve(int i)
    {
        if(i == n - 2) return Math.abs(arr[i] - arr[i + 1]);
        if(i == n - 1) return 0;
        if(memo[i] != null) return memo[i];

        int jump1 = Math.abs(arr[i] - arr[i + 1]) + solve(i + 1);
        int jump2 = Math.abs(arr[i] - arr[i + 2]) + solve(i + 2);
        return memo[i] = Math.min(jump1, jump2);
    }

