/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TimeLimitExceeded solver = new TimeLimitExceeded();
        solver.solve(1, in, out);
        out.close();
    }

    static class TimeLimitExceeded {
        public void solve(int testNumber, Scanner in, PrintWriter out) {

            int N = in.nextInt();
            int limitedTime = in.nextInt();

            Map<Integer, Integer> input = new TreeMap<>();

            // 経路値の入力の取得
            for (int i = 0; i < N; i++) {
                input.put(in.nextInt(), in.nextInt());
            }

            int ans = 0;
            for (Map.Entry<Integer, Integer> e : input.entrySet()) {
                if (e.getValue() <= limitedTime) {
                    ans = e.getKey();
                    break;
                }
            }

            if (ans == 0) {
                out.println("TLE");
                return;
            }

            out.println(ans);
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;


public class Main {

    int N,T;
    int[] c,t;
    private void solve() {
        N = nextInt();
        T = nextInt();
        c = new int[N];
        t = new int[N];

        for(int i = 0;i < N;i++) {
            c[i] = nextInt();
            t[i] = nextInt();
        }

        int ans = Integer.MAX_VALUE;
        for(int i = 0;i < N;i++) {
            if (t[i] <= T) {
                ans = Math.min(ans, c[i]);
            }
        }

        if (ans == Integer.MAX_VALUE) {
            out.println("TLE");
            return;
        }

        out.println(ans);
    }

    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

    /* Input */
    private static final InputStream in = System.in;
    private static final PrintWriter out = new PrintWriter(System.out);
    private final byte[] buffer = new byte[4096];
    private int p = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (p < buflen)
            return true;
        p = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (buflen <= 0)
            return false;
        return true;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrint(buffer[p])) {
            p++;
        }
        return hasNextByte();
    }

    private boolean isPrint(int ch) {
        if (ch >= '!' && ch <= '~')
            return true;
        return false;
    }

    private int nextByte() {
        if (!hasNextByte())
            return -1;
        return buffer[p++];
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

