		long[] cnt = new long[(MAX + 2)];

		cnt[1] = 1;
		for(int i = 3; i <= MAX; i++) cnt[i] = 2;
		for(int i=2; i<=MAX/2; i++) {
			for(int j = 2*i; j <= MAX; j += i) {cnt[j]++;}
		}

		for(int i = 0; i < MAX+2; i++) {
			if(i % 2 == 0) cnt[i] = 0;
		}
		return cnt;

	}
}

