        List<Integer> primes = primeList(200);

        int N = scanner.nextInt();

        int[] nums = new int[201];

        for(int i=1; i<=200; i++){
            for(int j=1; j<=i; j++){
                if(i%j == 0){
                    nums[i]++;
                }
            }
        }

        int cnt = 0;
