    public static int f(int n) {
        int sqrt = (int) Math.sqrt(n);
        int ans = 0;
        for (int i = 1; i <= sqrt; i++)
            if (n % i == 0) {
                ans++;
                if (i * i != n) ans++;
            }
        return ans;
    }

