	public String rotateString(String s,boolean direction) {
		if (s.length() == 0) {
			return s;
		}else {
			//右
			if (direction) {
				s = s.substring(s.length()-1, s.length()) + s.substring(0, s.length()-1);
			}else {
				s = s.substring(1) + s.substring(0, 1);
			}
			return s;
		}
	}

