class Solver {
  char[] ss, ts;
  int n;

  Solver(char[] ss, char[] ts) {
    this.ss = ss;
    this.ts = ts;
  }

  private boolean match(int offset) {
    for (int i = 0; i < n; i++) {
      if (ss[i] != ts[(i + offset) % n]) {
        return false;
      }
    }
    return true;
  }

  public boolean solve() {
    n = ss.length;
    for (int offset = 0; offset < n; offset++) {
      if (match(offset)) {
        return true;
      }
    }
    return false;
  }
}

