		String b = sc.next();
		char[] ac = a.toCharArray();
		char[] bc = b.toCharArray();
		int time = ac.length;
		while(time != 0) {

			if(Arrays.equals(ac, bc)) {
				break;
			}else {
				time--;
				rotate(ac);
			}
		}

		if(time == 0) {
			System.out.printf("No");
