        Scanner sc = new Scanner(System.in);
        int aCost = sc.nextInt();
        int bCost = sc.nextInt();
        int abCost = sc.nextInt();
        int A = sc.nextInt();
        int B = sc.nextInt();

        int sum1 = 0;
        int sum2 = 0;
        int sum3 = 0;
        int sum4 = 0;
        int sum5 = 0;

        if(A == B){
            sum1 += abCost*A*2;
            sum2 += abCost*A*2;
            sum3 += abCost*A*2;
            sum4 += abCost*A*2;
            sum5 += abCost*A*2;
        } else {
            sum1 += bCost*B + aCost*A;
            if(A-B < 0){
                sum2 += abCost*B*2;
                sum3 += abCost*B*2;
