public class Main {
	public static void main(String[] args) {
		try {

			BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

			String[] hyozyun = br.readLine().split(" ");
			int A =Integer.parseInt(hyozyun[0]);
			int B =Integer.parseInt(hyozyun[1]);
			int C =Integer.parseInt(hyozyun[2]);
			int X =Integer.parseInt(hyozyun[3]);
			int Y =Integer.parseInt(hyozyun[4]);

			// 合計金額を設定
			int sum = 0;
			// Cを２枚買ったほうが安い場合
			if (A + B < 2 * C) {
				sum = A * X + B * Y;
			} else {
			// それぞれ買ったほうが安い場合
				// 枚数少ないほうをすべて買って、プラス足りない分購入
				if (X > Y) {
					sum = C * 2 * Y + (X - Y) * A;
				} else {
					sum = C * 2 * X + (Y - X) * B;
				}
			}
			// XとYの枚数が多いほうの分だけ、Cを買った場合の値段
			int compare = 0;
			if (X > Y) {
				compare = X * C * 2;
			} else {
				compare = Y * C * 2;
			}
			// 上記の計算結果のほうが安い場合はそちらを採用
			if (sum > compare) {
				sum = compare;
			}

			System.out.println(sum);
		} catch (Exception e) {
			e.printStackTrace();
		}
	}
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int A = sc.nextInt();
        int B = sc.nextInt();
        int C = sc.nextInt();
        int X = sc.nextInt();
        int Y = sc.nextInt();

        System.out.println(solve(A, B, C, X, Y));

        sc.close();
    }

    static int solve(int A, int B, int C, int X, int Y) {
        return Math.min(A + B, C * 2) * Math.min(X, Y) + Math.min(A, C * 2) * Math.max(0, X - Math.min(X, Y))
                + Math.min(B, C * 2) * Math.max(0, Y - Math.min(X, Y));
    }
}

