        int ans = 2;
        if(a+b <= c*2) {
            ans = a*x + b*y;
        }else {
            if(a <= c*2 && b <= c*2) { 
                if(x >= y) ans = c*2*y + a*(x-y);
                else ans = c*2*x + b*(y-x);
            }else if(a >= c*2 && b <= c*2) {
                if(x >= y) ans = c*2*x;
                else ans = c*2*x + b*(y-x);
            }else if(a <= c*2 && b >= c*2) {
                if(y >= x) ans = c*2*y;
                else ans = c*2*y + a*(x-y);
            }else {
                ans = c*2*max(x,y);
            }
        }
        System.out.println(ans);
    }

    static int max(int x, int y) {
        if(x >= y) return x;
        else return y;
    }

    static int min(int x, int y) {
        if(x >= y) return y;
        else return x;
    }
}

