/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author HBonsai
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CHalfAndHalf solver = new CHalfAndHalf();
        solver.solve(1, in, out);
        out.close();
    }

    static class CHalfAndHalf {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int A = in.nextInt();
            int B = in.nextInt();
            int C = in.nextInt();
            int X = in.nextInt();
            int Y = in.nextInt();
            int ans = A * X + B * Y;
            if (A + B >= C * 2) {
                if (Y >= X) {
                    if (B >= C * 2) {
                        ans = C * 2 * Y;
                    } else {
                        ans = C * 2 * X + B * (Y - X);
                    }
                } else {
                    if (A >= C * 2) {
                        ans = C * 2 * X;
                    } else {
                        ans = C * 2 * Y + A * (X - Y);
                    }
                }
            }
            out.println(ans);
        }

    }

    static class FastScanner implements Closeable {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
            return hasNextByte();
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }

        public void close() {
            try {
                in.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            int c = sc.nextInt();
            int x = sc.nextInt();
            int y = sc.nextInt();

            // 0. すべてAとBを買うときの金額を初期値とする。
            int ans = a * x + b * y;
            // 1. AとBを2xCに交換し、合計金額の減少or増加を確認する
            // このとき、Cは2枚セットで交換する必要があることに注意
            // 1-1. 合計金額が減少する場合は処理を継続
            // 1-2. 合計金額が減少しない場合は処理を終了
            int max = Math.max(x, y);
            for (int i = 0; i < max; i++) {
                int deltaX = Math.min(x, 1);
                int deltaY = Math.min(y, 1);
                int candidate = ans - (a * deltaX + b * deltaY) + 2 * c * Math.max(deltaX, deltaY);
                if (candidate < ans) {
                    ans = candidate;
                    x -= deltaX;
                    y -= deltaY;
                } else {
                    break;
                }
            }

            System.out.println(ans);
        }
    }

}

