			for (int j = 0; j < n; j++) {
				if (j < i) {
					sum += a[0][j];
				} else if (j == i) {
					sum += a[0][j];
					sum += a[1][j];
				} else {
					sum += a[1][j];
				}
			}
			ans = Math.max(ans, sum);
		}
		System.out.println(ans);
	}
}

