					dp[i][j] = Math.max(dp[i][j - 1] + a[i][j], dp[i + 1][j] + a[i][j]);
				} else if(i == 1) {
					dp[i][j] = Math.max(dp[i - 1][j] + a[i][j], dp[i][j - 1] + a[i][j]);
				}
			}
		}
		System.out.println(dp[1][n - 1]);
	}
}

