class Main {
    private static int calcScore(int[][] a, int down) {

        int count = 0;
        for (int j = 0; j < a[0].length; j++) {
            if (j == down) {
                count += a[0][j];
                count += a[1][j];
            }else if( j < down){
                count += a[0][j];
            }else  if(j > down){
                count += a[1][j];               
            }
        }
        return count;
    }

