    public static class Task {

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int n = sc.nextInt();
            int[] prefix = new int[n];
            int[] suffix = new int[n];
            int[] a = new int[n];
            int[] b = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = sc.nextInt();
            }
            for (int i = 0; i < n; i++) {
                b[i] = sc.nextInt();
            }
            prefix[0] = a[0];
            suffix[n - 1] = b[n - 1];
            for (int i = 1; i < n; i++) {
                prefix[i] = a[i] + prefix[i - 1];
            }
            for (int i = n - 2; i >= 0; i--) {
                suffix[i] = b[i] + suffix[i + 1];
            }
            int max = 0;
            for (int i = 0; i < n; i++) {
                max = Math.max(max, prefix[i] + suffix[i]);
            }
            pw.println(max);
        }

