        int c[] = new int[n];

        for (int i = 0; i < n; i++) {
            b[i] = s.nextInt();
        }
        for (int i = 0; i < n; i++) {
            c[i] = s.nextInt();
        }

        int max = 0;
        int temp = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                temp += b[j];
            }
            for (int j = i-1; j < n; j++) {
                temp += c[j];
            }
            if (temp >= max) {
                max = temp;
            }
            temp = 0;
        }

        System.out.println(max);
    }
}

