import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        int n = in.nextInt();
        int y = in.nextInt();
        if ((y - 1000 * n) % 1000 != 0) {
            out.println("-1 -1 -1");
            out.close();
            return;
        } else {
            int cnt = (y - 1000 * n) / 1000;
            for (int i=0; i<=cnt / 4; i++) {
                int other = (y - 1000 * n) / 1000 - 4 * i;
                if (other % 9 == 0 && (n - i - (other / 9)) >= 0) {
                    out.println((other / 9) + " "  + (i) + " " + (n - i - (other / 9)));
                    out.close();
                    return;
                }
            }
        }
        out.println("-1 -1 -1");

        out.close();
        //INT OVERFLOW -> USE LONG
        //ARR OUT OF BOUNDS
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public Scanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

