	// 偶数かどうかを判定
	static boolean isEven(int n){
		if(n%2 == 0){
			return true;
		}else{
			return false;
		}
	}

	// 2で割り切れる回数を取得
	static int NumberOfDevision(int[] values){
		for(int i = 0; i < values.length; i++){
			if(isEven(values[i])){
				values[i] = values[i]/2;
			}else{
				return 0;
			}
		}
		return 1 + NumberOfDevision(values);
	}
}

