				t[now]++;
				now = 0;
				break;
			case 'b':
				t[now]++;
				now = 1;
				break;
			case 'c':
				t[now]++;
				now = 2;
				break;
			}

			if(t[0]==Sa.length()&&now==0) {
				ans = "A";
				break;
			}
