        ArrayDeque<Character> a = new ArrayDeque<>();
        ArrayDeque<Character> b = new ArrayDeque<>();
        ArrayDeque<Character> c = new ArrayDeque<>();
        char[] sa = in.ns().toCharArray();
        char[] sb = in.ns().toCharArray();
        char[] sc = in.ns().toCharArray();
        for(char i: sa) a.addLast(i);
        for(char i: sb) b.addLast(i);
        for(char i: sc) c.addLast(i);
        char player = 'a';
        while(true){
            if(player=='a'){
                if(!a.isEmpty()){
                    player = a.pollFirst();
                }else break;
            }else if(player=='b'){
                if(!b.isEmpty()){
                    player = b.pollFirst();
                }else break;
            }else{
                if(!c.isEmpty()){
                    player = c.pollFirst();
                }else break;
            }
        }
        out.println((char)(player+'A'-'a'));
    }

