class AtCoder {

    char[] A, B, C;

    AtCoder(FastScanner sc) {
        A = sc.next().toCharArray();
        B = sc.next().toCharArray();
        C = sc.next().toCharArray();
    }

    void solve(PrintWriter out) {
        int index_a = 0, index_b = 0, index_c = 0;
        char c = A[index_a];
        index_a++;
        while (true) {
            if (A.length == index_a && c == 'a'
                    || B.length == index_b && c == 'b'
                    || C.length == index_c && c == 'c') break;
            if (c == 'a') {
                c = A[index_a];
                index_a++;
            } else if (c == 'b') {
                c = B[index_b];
                index_b++;
            } else {
                c = C[index_c];
                index_c++;
            }
        }
        if (c == 'a') {
            out.println('A');
        } else if (c == 'b') {
            out.println('B');
        } else {
            out.println('C');
        }
    }

}

