    static int serch(int thisTurn) {
        if (cnt[thisTurn] <= 0)
            return thisTurn;

        int index =  S[thisTurn].length() - cnt[thisTurn];
        char c = S[thisTurn].charAt(index);
        cnt[thisTurn]--;

        if (c == 'a')
            return serch(0);
        else if (c == 'b')
            return serch(1);
        else
            return serch(2);
    }
}

