        System.out.println("A");
        break;
      }
      else next = A.charAt(counterA-1);
    }
    else if(next == 'b'){
      counterB++;
      if(counterB == B.length()+1){
        System.out.println("B");
        break;
      }
      else next = B.charAt(counterB-1);
    }
    else if(next == 'c'){
      counterC++;
      if(counterC == C.length()+1){
        System.out.println("C");
        break;
      }
      else next = C.charAt(counterC-1);
    }
  }
}}

