class Main {
    public static void main(String[] args) throws IOException {
        String[] cards = new String[3];
        cards[0] = receive();
        cards[1] = receive();
        cards[2] = receive();

        int player = 0, next;
        while(true) {
            if(cards[player].length() == 0) break;
            next = cards[player].charAt(0) - 'a';
