	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			Deque<Integer> stack = new ArrayDeque<Integer>();

			char[] s = in.nextString().toCharArray();
			for (char c : s) {
				if (c == '0') {
					stack.push(0);
				} else if (c == '1') {
					stack.push(1);
				} else if (c == 'B') {
					if (stack.isEmpty()) continue;
					stack.pop();
				}
			}

