                st.push(1);
                count++;
            }
            else if(s.charAt(i) == 'B') {
                if(count == 0){
                    // do nothing
                } else {
                    st.pop();
                    count--;
                }
            }
        }
        for(int i=0; i<count; i++){
            System.out.print(st.get(i));
        }
    }
}

